import { NextResponse } from "next/server";

import User, { type IUserDoc } from "@/database/user.model";
import handleError from "@/lib/handlers/error";
import { parseJsonBody } from "@/lib/handlers/parse-json-body";
import { NotFoundError } from "@/lib/http-errors";
import dbConnect from "@/lib/mongoose";
import { UserSchema } from "@/lib/validations";
import type { APIResponse } from "@/types";

// RouteContext is generated by Next from the folder path, so params is
// typed as Promise<{ id: string }>. An invalid id ("abc") makes Mongoose
// throw a CastError, which handleError answers with a 400.
type Context = RouteContext<"/api/users/[id]">;

// GET /api/users/[id]
export async function GET(
  _request: Request,
  { params }: Context,
): Promise<APIResponse<IUserDoc>> {
  try {
    const { id } = await params;
    await dbConnect();

    const user = await User.findById(id).lean<IUserDoc>();
    if (!user) throw new NotFoundError("User");

    return NextResponse.json({ success: true, data: user });
  } catch (error) {
    return handleError(error, "api");
  }
}

// PUT /api/users/[id]: updates only the fields that are sent
export async function PUT(
  request: Request,
  { params }: Context,
): Promise<APIResponse<IUserDoc>> {
  try {
    const { id } = await params;
    const data = UserSchema.partial().parse(await parseJsonBody(request));

    await dbConnect();

    // Mongoose skips schema validation on updates unless runValidators is
    // set. A taken email or username fails the unique index -> 409.
    const updatedUser = await User.findByIdAndUpdate(id, data, {
      returnDocument: "after",
      runValidators: true,
    }).lean<IUserDoc>();
    if (!updatedUser) throw new NotFoundError("User");

    return NextResponse.json({ success: true, data: updatedUser });
  } catch (error) {
    return handleError(error, "api");
  }
}

// DELETE /api/users/[id]: returns the deleted user
export async function DELETE(
  _request: Request,
  { params }: Context,
): Promise<APIResponse<IUserDoc>> {
  try {
    const { id } = await params;
    await dbConnect();

    const deletedUser = await User.findByIdAndDelete(id).lean<IUserDoc>();
    if (!deletedUser) throw new NotFoundError("User");

    return NextResponse.json({ success: true, data: deletedUser });
  } catch (error) {
    return handleError(error, "api");
  }
}
